function reciprocalForm(){const a=arithmeticTask,field=(name,label,value)=>`<input autocomplete="off" autocorrect="off" spellcheck="false" data-expression-field name="${name}" aria-label="${label}" inputmode="text" pattern="[-−]?[0-9]+" maxlength="81" value="${esc(value)}" required>`;return `<form autocomplete="off" id="arithmetic-form"><label>Reciproco del divisore <span class="fraction reciprocal-answer"><span>${field('answer','Numeratore del reciproco',a.numerator)}</span><span>${field('denominator','Denominatore del reciproco',a.denominator)}</span></span></label><button>Verifica</button><button type="button" data-action="cancel-arithmetic" aria-label="Annulla passaggio" title="Annulla passaggio">↶</button><span role="alert">${esc(a.error)}</span></form>`;}
function finishReciprocal(event){const a=arithmeticTask;try{const data=new FormData(event.target);a.numerator=String(data.get('answer')).trim().replace('−','-');a.denominator=String(data.get('denominator')).trim().replace('−','-');if(![a.numerator,a.denominator].every(v=>/^-?\d{1,80}$/.test(v)))throw Error('Scrivi numeratore e denominatore con numeri interi.');const n=BigInt(a.numerator),d=BigInt(a.denominator);if(!d)throw Error('Il denominatore non può essere zero.');const t=E.find(current(),a.id),divisor=E.evaluate(t.right);if(!divisor.n)throw Error('Zero non ha reciproco.');if(n*divisor.n!==d*divisor.d)throw Error('Il reciproco non torna. Controlla numeratore, denominatore e segno.');const right=E.fraction(E.num(n),E.num(d)),next=E.node('binary',{op:'·',left:structuredClone(t.left),right});arithmeticTask=null;change(t.id,next,'Divisione trasformata con il reciproco scritto dallo studente',true);keypad.suspend();}catch(error){arithmeticTask=a;a.error=error.message;renderContext();}}
function arithmeticForm(){if(arithmeticTask.kind==='monomial')return monomialForm();if(arithmeticTask.kind==='generating')return generatingForm();if(arithmeticTask.kind==='power')return powerForm();if(arithmeticTask.kind==='reciprocal')return reciprocalForm();if(arithmeticTask.kind==='product')return productForm();const t=E.find(current(),arithmeticTask.id),values=arithmeticTask.kind==='addition'?signedNumerators(t):null,{a,b}=values?{a:[values[0]],b:[values[1]]}:arithmeticTerms(t);return `<form autocomplete="off" id="arithmetic-form"><label>${values?values.map((v,i)=>i?(v<0n?' − '+(-v):' + '+v):String(v)).join(''):(a[0]+' '+t.op+' '+b[0])} = <input autocomplete="off" autocorrect="off" spellcheck="false" data-expression-field name="answer" aria-label="${t.op==='+'?'Somma':'Differenza'} dei ${t.left.type==='fraction'||isNumerator(t.id)?'numeratori':'numeri'}" inputmode="text" pattern="[-−]?[0-9]+" maxlength="81" required></label><button>Verifica</button><button type="button" data-action="cancel-arithmetic" aria-label="Annulla passaggio" title="Annulla passaggio">↶</button><span role="alert">${esc(arithmeticTask.error)}</span></form>`;}
function contextActions(){if(!rows.length||!selected.length)return[];const t=selected.length===1?E.find(current(),selected[0]):null,out=[];if(E.hasVariables(current())){if(monomialSelection())out.push(['monomial-sum','Somma monomi simili']);const f=fractionOrNull(t);if(f&&E.gcd(...f)>1n)out.push(['simplify','Semplifica']);if(t&&activeRow===rows.length-1)out.push(['edit','Modifica'],['delete','⌫']);return out;}
 if(t?.type==='number'&&/^-?[0-9]+[.,]/.test(t.value))out.push(['generate','Scrivi frazione generatrice']);
 if(compoundFraction())out.push(['reciprocal','Trasforma in moltiplicazione']);
 const f=fractionOrNull(t);if(f&&E.gcd(...f)>1n)out.push(['simplify','Semplifica']);
 const powers=powerOptions();if(powers.single&&powers.base)out.push(['power-calculate','Esegui la potenza']);if(powers.product)out.push(['power-product','Prodotto di potenze']);if(powers.quotient)out.push(['power-quotient','Quoziente di potenze']);if(powers.nested)out.push(['power-nested','Potenza di potenza']);if(powers.rewrite)out.push(['power-rewrite','Riscrivi base come potenza']);const product=productSelection(),cross=crossSelection();if(cross)out.push(['cross','Semplifica in croce']);if(product){if(distributionFor(product))out.push(['distribute','Distributiva']);if(product.terms.every(naturalFraction)&&product.terms.filter(t=>fractionOrNull(t)).length>=1)out.push(['pick-cross','Semplifica in croce']);if(product.terms.every(naturalFraction))out.push(['product','Esegui il prodotto']);if(product.termIds.length===2)out.push(['product-swap','Commutativa']);}const addition=additionSelection(),operation=arithmeticFor();if(addition){if(addition.terms.every(naturalFraction))out.push(['arithmetic',addition.signs.some(s=>s<0)?(addition.termIds.length===2&&addition.signs[0]===1&&addition.signs[1]===-1?'Esegui la sottrazione':'Esegui somma e differenza'):'Esegui la somma']);if(addition.termIds.length===2)out.push(['commutative','Commutativa']);}else if(operation)out.push(['arithmetic',operation.op==='+'?'Esegui la somma':'Esegui la sottrazione']);
 if(divisionFor())out.push(['reciprocal','Trasforma in moltiplicazione']);
 if(t&&activeRow===rows.length-1)out.push(['edit','Modifica'],['delete','⌫']);

 return out;}
function renderContext(){const box=$('#actions');if(fractionWork?.active()){box.hidden=false;box.innerHTML=fractionWork.form();window.GatitoExpressionInputs?.prepare(box);positionContext();fractionWork.focus();return;}if(arithmeticTask){box.hidden=false;box.innerHTML=arithmeticForm();window.GatitoExpressionInputs?.prepare(box);positionContext();box.querySelector('input')?.focus({preventScroll:true});return;}if(crossPicking){box.hidden=false;box.innerHTML='<span>Seleziona un numeratore e un denominatore.</span><button type="button" data-action="end-cross">Fine</button>';positionContext();return;}const items=contextActions();box.hidden=!items.length;box.innerHTML=items.map(([id,label])=>`<button type="button" data-action="${id}" ${id==='commutative'?'title="Scambia gli addendi"':id==='product-swap'?'title="Scambia i fattori"':''}>${label}</button>`).join('');positionContext();}
function positionContext(){const box=$('#actions');if(box.hidden)return;const anchor=[...document.querySelectorAll(`#rows [data-row="${activeRow}"] [data-token]`)].find(el=>el.dataset.token===(fractionWork?.anchor()||(arithmeticTask?.kind==='monomial'?(arithmeticTask.stage==='sum'?arithmeticTask.id:arithmeticTask.plan.termIds[0]):arithmeticTask?(E.find(currentOrNull(),arithmeticTask.id)?.type==='binary'?arithmeticTask.id+'op':arithmeticTask.id):selected.at(-1)||crossPicking?.termIds[0])))||(arithmeticTask?.kind==='monomial'?document.querySelector(`#rows [data-row="${activeRow}"] .formula`):null);if(!anchor)return;const whole=(['reciprocal','power','generating','monomial'].includes(arithmeticTask?.kind)?anchor.closest('.formula'):anchor.closest('.fraction,.em-power,.group'))||anchor;const r=whole.getBoundingClientRect();box.style.left=Math.max(8,Math.min(r.left,innerWidth-box.offsetWidth-8))+'px';let top=r.bottom+18;if(top+box.offsetHeight>innerHeight-8)top=Math.max(8,r.top-box.offsetHeight-18);box.style.top=top+'px';}
window.addEventListener('resize',positionContext);document.addEventListener('scroll',positionContext,true);
function currentOrNull(){return rows[activeRow]?.tree||null;}
function current(){if(!rows.length)throw Error('Inserisci prima un’espressione.');return rows[activeRow].tree;}
function chosen(){if(selected.length!==1)throw Error('Seleziona una sola parte dell’espressione.');const t=E.find(current(),selected[0]);if(!t)throw Error('Seleziona il numero, la frazione o il gruppo.');return t;}
function change(id,next,note,newRow=false,rebase,selectedIds){const result=GatitoExpressionSteps.apply(rows,activeRow,{id,next,note,newRow,rebase,selectedIds},E);remember();rows=result.rows;activeRow=result.index;selected=[];message('');render();}
function additionRebase(ids,replacement,swap=false){return tree=>{const scope=GatitoExpressionAddition.signedScopes(tree).find(t=>{const terms=GatitoExpressionAddition.signedFlatten(t).terms;return ids.every(id=>terms.some(n=>n.id===id));});if(!scope)throw Error('Questi addendi sono già stati trasformati in un altro passaggio.');const next=swap?GatitoExpressionAddition.signedSwap(scope,ids,E):GatitoExpressionAddition.signedCollect(scope,ids,structuredClone(replacement),E);return E.replace(tree,scope.id,next);};}
function toggleToken(id){if(selected.includes(id)){selected=selected.filter(x=>x!==id);return;}const tree=current(),contains=(node,key)=>!!node&&(!!E.find(node,key)||key.endsWith('op')&&!!E.find(node,key.slice(0,-2))),target=E.find(tree,id);selected=selected.filter(key=>!contains(target,key)&&!contains(E.find(tree,key),id));selected.push(id);}
$('#rows').addEventListener('click',e=>{if(e.target.closest('[data-continue]')){if(arithmeticTask||fractionWork?.active())return;activeRow=Number(e.target.closest('[data-row]').dataset.row);actions.checkpoint();return;}const el=e.target.closest('[data-token]');if(!el||arithmeticTask||fractionWork?.active())return;const index=Number(el.closest('[data-row]').dataset.row);if(activeRow!==index){activeRow=index;selected=[];crossPicking=null;}const id=el.dataset.token;if(crossPicking){if(!crossCandidates().includes(id))return;toggleToken(id);if(selected.length>2)selected=selected.slice(-2);const pair=crossSelection();if(pair&&[pair.top.owner,pair.bottom.owner].every(owner=>crossPicking.termIds.includes(owner))){safe(()=>startCross(pair));return;}render();return;}toggleToken(id);render();keypad?.selectSaved();});$('#rows').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-token]')){e.preventDefault();e.target.click();}});
function safe(fn){try{fn();}catch(e){message(e.message);}}

function undo(){if(crossPicking&&!fractionWork?.active()){crossPicking=null;selected=[];render();return;}if(arithmeticTask){arithmeticTask=null;render();return;}if(fractionWork?.active()){afterCommon=null;crossTask=null;crossPicking=null;fractionWork.cancel();return;}if(!past.length)return;redo.push(structuredClone(rows));rows=past.pop();activeRow=rows.length-1;selected=[];message('');render();}
function redoStep(){if(!redo.length)return;past.push(structuredClone(rows));rows=redo.pop();activeRow=rows.length-1;selected=[];message('');render();}
const actions={generate:()=>safe(startGenerating),
reciprocal:()=>safe(()=>{const t=divisionFor()||compoundFraction();if(!t)throw Error('Seleziona una divisione oppure una frazione con numeratore e denominatore già ridotti a singoli numeri o frazioni.');if(!E.evaluate(t.right).n)throw Error('Zero non ha reciproco.');arithmeticTask={kind:'reciprocal',id:t.id,numerator:'',denominator:'',error:''};render();}),
checkpoint:()=>safe(()=>{if(arithmeticTask||fractionWork.active())throw Error('Completa prima il passaggio in corso.');const next=restore(current());function clean(t){delete t.fractionInk;if(t.child)clean(t.child);if(t.left){clean(t.left);clean(t.right);}}clean(next);const linked=structuredClone(current());GatitoExpressionSteps.clean(linked);remember();rows.splice(activeRow+1,0,{tree:linked,note:'Passaggio conservato',family:rows[activeRow].family,locks:[]});activeRow++;selected=[];render();keypad.suspend();})};
$('#actions').onclick=e=>{const tool=e.target.closest('[data-fw]')?.dataset.fw;if(tool){if(tool==='cancel'){afterCommon=null;crossTask=null;crossPicking=null;fractionWork.cancel();}else{keypad.suspend();fractionWork.factor(tool);}return;}const action=e.target.closest('[data-action]')?.dataset.action;if(action)actions[action]?.();};
document.addEventListener('pointerdown',e=>{if(arithmeticTask||fractionWork?.active()||!selected.length||e.target.closest('[data-continue],[data-token],#actions,#keyboard,dialog,#toggle'))return;selected=[];render();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]')){if(fractionWork?.active()){afterCommon=null;crossTask=null;crossPicking=null;fractionWork.cancel();}else{arithmeticTask=null;crossPicking=null;selected=[];render();}}});
let task=null;
function fractionValues(t){if(t.type!=='fraction'||t.left.type!=='number'||t.right.type!=='number'||!/^-?\d+$/.test(t.left.value)||!/^\d+$/.test(t.right.value))throw Error('Seleziona una frazione con numeratore intero e denominatore positivo già calcolati.');return[BigInt(t.left.value),BigInt(t.right.value)];}
function dialog(title,fields,help){$('#dialog-title').textContent=title;$('#fields').innerHTML=fields.map(([name,label])=>`<label>${label}<input autocomplete="off" autocorrect="off" spellcheck="false" name="${name}" inputmode="numeric" required pattern="[0-9]+" maxlength="80"></label>`).join('');window.GatitoExpressionInputs?.prepare($('#fields'));$('#help-text').textContent=help;$('#help').open=false;$('#dialog-error').textContent='';$('#work').showModal();}
fractionWork=GatitoExpressionFractionWork.create({onRender:render,onMessage:message,isSelected:id=>paintingRow===activeRow&&selected.includes(id),onApply(updates){if(crossTask){applyCross(updates);return;}let tree=structuredClone(current());for(const u of updates){const old=E.evaluate(E.find(tree,u.id)),next=E.evaluate(u.tree);if(old.n*next.d!==next.n*old.d)throw Error('Il passaggio cambia il valore della frazione.');tree=E.replace(tree,u.id,u.tree);}update(tree,'Proprietà invariantiva');if(afterCommon){const plan=afterCommon;afterCommon=null;if(typeof plan==='string')startArithmetic(plan);else startAddition({...plan,termIds:plan.termIds.map(id=>updates.find(u=>u.id===id)?.tree.id||id)});}}});
actions['monomial-sum']=()=>safe(startMonomial);
actions['pick-cross']=()=>safe(()=>beginCrossPicking(productSelection()));
actions['end-cross']=()=>{crossPicking=null;selected=[];message('');render();};
actions.cross=()=>safe(()=>startCross(crossSelection()));
for(const rule of ['calculate','product','quotient','nested','rewrite'])actions['power-'+rule]=()=>safe(()=>startPower(rule));
actions.distribute=()=>safe(distributeProduct);
actions.product=()=>safe(()=>startProduct(productSelection()));
actions['product-swap']=()=>safe(()=>{const plan=productSelection(),scope=E.find(current(),plan.scopeId);change(scope.id,GatitoExpressionProduct.swap(scope,plan.termIds,E),'Proprietà commutativa del prodotto',false,productRebase(plan.termIds,null,true),plan.termIds);});
actions.simplify=()=>safe(()=>fractionWork.start('simplify',[chosen()]));
actions.arithmetic=()=>safe(()=>{const plan=additionSelection();if(plan)startAddition(plan);else{const operation=arithmeticFor();if(operation.split){const source=operation.split,pair=E.node('binary',{op:'−',left:structuredClone(operation.left),right:structuredClone(operation.right)}),next=E.node('binary',{op:'+',left:structuredClone(source.left.left),right:pair});change(source.id,next,'Sottrazione raccolta nella somma',false,null,selected);startArithmetic(pair.id);}else startArithmetic(operation.id);}});
actions.commutative=()=>safe(()=>{const plan=additionSelection();if(!plan||plan.termIds.length!==2)throw Error('Seleziona due addendi e il segno +.');const scope=E.find(current(),plan.scopeId);change(scope.id,GatitoExpressionAddition.signedSwap(scope,plan.termIds,E),'Proprietà commutativa',false,additionRebase(plan.termIds,null,true),plan.termIds);});
actions['cancel-arithmetic']=()=>{arithmeticTask=null;selected=[];render();};
$('#actions').addEventListener('keydown',event=>{if(!['ArrowUp','ArrowDown'].includes(event.key)||event.ctrlKey||event.metaKey||event.altKey)return;const fraction=event.target.closest('.reciprocal-answer');if(!fraction)return;const fields=[...fraction.querySelectorAll('input')],index=fields.indexOf(event.target),next=fraction.classList.contains('generating-answer')?(event.key==='ArrowDown'?fields.at(-1):fields[0]):fields[index+(event.key==='ArrowDown'?1:-1)];if(index<0||!next)return;event.preventDefault();const cursor=Math.min(event.target.selectionStart??next.value.length,next.value.length);next.focus({preventScroll:true});next.setSelectionRange(cursor,cursor);});
$('#actions').addEventListener('submit',event=>{if(event.target.id!=='arithmetic-form'||!arithmeticTask)return;event.preventDefault();if(arithmeticTask.kind==='monomial'){finishMonomial(event);return;}if(arithmeticTask.kind==='generating'){finishGenerating(event);return;}if(arithmeticTask.kind==='power'){finishPower(event);return;}if(arithmeticTask.kind==='reciprocal'){finishReciprocal(event);return;}if(arithmeticTask.kind==='product'){finishProduct(event);return;}const completing=arithmeticTask;try{const raw=String(new FormData(event.target).get('answer')).trim().replace('−','-');if(!/^-?\d{1,80}$/.test(raw))throw Error('Scrivi tu il risultato con un numero intero, anche negativo.');const t=E.find(current(),arithmeticTask.id),values=arithmeticTask.kind==='addition'?signedNumerators(t):null,{a,b}=values?{a:[values[0]],b:[values[1]]}:arithmeticTerms(t),expected=values?values.reduce((x,y)=>x+y,0n):t.op==='+'?a[0]+b[0]:a[0]-b[0];if(BigInt(raw)!==expected)throw Error('Il risultato non torna. Riprova.');const id=t.id,answer=E.num(String(BigInt(raw))),next=values||t.left.type==='number'&&t.right.type==='number'?answer:E.fraction(answer,E.num(a[1]));arithmeticTask=null;change(id,next,'Operazione scritta dallo studente',true);keypad.suspend();}catch(error){arithmeticTask=completing;arithmeticTask.error=error.message;renderContext();}});
actions.edit=()=>safe(()=>{if(activeRow!==rows.length-1)throw Error('Per cambiare i dati usa l’ultima riga.');keypad.editSaved(current(),chosen().id);});
actions.delete=()=>safe(()=>{if(activeRow!==rows.length-1)throw Error('Per cancellare usa l’ultima riga.');keypad.editSaved(current(),chosen().id,true);});
$('#actions').addEventListener('submit',event=>{if(event.target.id!=='fraction-work-form')return;event.preventDefault();fractionWork.submit(new FormData(event.target).get('answer'));});
$('#work-form').onsubmit=e=>{e.preventDefault();try{const data=new FormData(e.target);const value=k=>{const s=data.get(k);if(!/^\d{1,80}$/.test(s))throw Error('Completa tutte le risposte con numeri naturali.');return BigInt(s);};if(task.kind==='generate'){const n=value('n'),d=value('d');if(n!==task.n||d!==task.d)throw Error('Controlla la costruzione del numeratore e del denominatore della frazione generatrice.');change(task.id,E.fraction(E.num(n*task.sign),E.num(d)),'Frazione generatrice');}else if(task.kind==='simplify'){const k=value('k'),n=value('n'),d=value('d');if(k<=1n||task.n%k||task.d%k)throw Error('Scegli un divisore comune maggiore di 1.');if(n!==task.n/k||d!==task.d/k)throw Error('Controlla i due quozienti.');change(task.id,E.fraction(E.num(n),E.num(d)),`Semplificazione: entrambi i termini divisi per ${k}`);}else{const d=value('d'),a=value('a'),b=value('b');if(!d||d%task.ad||d%task.bd)throw Error('Il denominatore deve essere un multiplo di entrambi.');if(a!==task.an*(d/task.ad)||b!==task.bn*(d/task.bd))throw Error('Controlla i prodotti dei numeratori.');let tree=structuredClone(current());tree=E.replace(tree,task.a,E.fraction(E.num(a),E.num(d)));tree=E.replace(tree,task.b,E.fraction(E.num(b),E.num(d)));update(tree,'Frazioni equivalenti con denominatore '+d);}$('#work').close();}catch(error){$('#dialog-error').textContent=error.message;}};
$('#close-work').onclick=()=>$('#work').close();
actions.rewrite=()=>safe(()=>{const t=chosen();task={id:t.id};$('#rewrite-entry').value='';$('#rewrite-error').textContent='';$('#rewrite-original').innerHTML=math(t,false);$('#rewrite-dialog').showModal();});$('#rewrite-form').onsubmit=e=>{e.preventDefault();try{change(task.id,E.parse($('#rewrite-entry').value),'Passaggio scritto dallo studente');$('#rewrite-dialog').close();}catch(error){$('#rewrite-error').textContent=error.message;}};$('#close-rewrite').onclick=()=>$('#rewrite-dialog').close();
keypad=GatitoExpressionKeyboard.mount({commit:(source,pick)=>{const tree=E.parse(source);add(tree,'Espressione iniziale');if(pick){const nodes=[];function visit(t){if(t.type===pick.type)nodes.push(t);if(t.child)visit(t.child);if(t.left){visit(t.left);visit(t.right);}}visit(tree);selected=[nodes[pick.index]?.id].filter(Boolean);render();}},onSelectionChange:renderContext,undo,redo:redoStep,canUndo:()=>!!past.length,canRedo:()=>!!redo.length,getMathSelection(){const tree=currentOrNull();if(!tree)return null;const nodes=selected.map(id=>E.find(tree,id)).filter(Boolean);if(nodes.length!==selected.length)return null;const roots=nodes.filter(n=>!nodes.some(other=>other!==n&&E.find(other,n.id)));return roots.length===1?{kind:'saved',tree,node:roots[0],readOnly:activeRow!==rows.length-1}:null;},takeMathSelection(){if(activeRow!==rows.length-1)throw Error('Taglia e modifica nell’ultima riga.');if(rows.length){remember();rows.pop();activeRow=rows.length-1;}selected=[];render();},getDecimalSelection(){if(selected.length!==1)return null;const n=E.find(current(),selected[0]);return n?.type==='number'&&GatitoExpressionDecimals.decimal(n.value)?{id:n.id,value:n.value}:null;},setDecimalPeriod(id,value){const number=E.num(value),tree=E.replace(structuredClone(current()),id,number);E.evaluate(tree);if(activeRow!==rows.length-1)throw Error('Modifica il periodo nell’ultima riga.');remember();rows[activeRow]={...rows[activeRow],tree};selected=[];render();selected=[number.id];render();}});
render();

$('#generate-expression').onclick=()=>safe(()=>{const level=$('#expression-level').value;const exercise=window.GatitoExpressionGenerator.generate(level,($('#include-decimals')?.checked||false));add(exercise.tree,'Espressione generata · '+({base:'Base',medio:'Intermedia',avanzato:'Avanzata',nightmare:'Nightmare'}[level]));$('#rows .expression-sheet:last-child')?.scrollIntoView({block:'nearest',behavior:'smooth'});});

$('#empty-slot').onclick=()=>keypad.open();$('#paper').addEventListener('dblclick',event=>{if(fractionWork.active()||event.target.closest('[data-token],#actions,input,button,#keyboard'))return;keypad.open();});$('#clear-paper').onclick=()=>{arithmeticTask=null;afterCommon=null;crossTask=null;crossPicking=null;fractionWork.cancel();remember();rows=[];activeRow=-1;selected=[];message('');render();keypad.clear();$('#keyboard').hidden=true;};




// Keep answer boxes proportional to the number being written.
document.addEventListener('input',event=>{if(event.target.matches('#rows input[data-expression-field]')){event.target.style.setProperty('--answer-digits',Math.min(12,Math.max(2,event.target.value.length)));positionContext();}});
